    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Fill the interior of complete rectangle outlines with color 4.
    from collections import Counter
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    outline = next(v for row in g for v in row if v != bg)
    for r1 in range(h):
        for r2 in range(r1 + 2, h):
            for c1 in range(w):
                for c2 in range(c1 + 2, w):
                    if (all(g[r1][c] == outline for c in range(c1, c2 + 1)) and
